$ErrorActionPreference = 'Continue'
# 28.10.2026: hero comes alive (blinks, gaze, breathing). Keep the v2 clips in clips\v2 (copy), then re-render 20 hero shots
$C = 'C:\Users\Gigabyte\Documents\aipollon claude\sposobnosti\clips'
New-Item -ItemType Directory -Force -Path "$C\v2" | Out-Null
