"BACKUP " + (Get-ChildItem "$C\v2\*.mp4").Count + " clips in clips\v2"
$B = (Get-Content 'C:\Users\Gigabyte\Documents\aipollon claude\sposobnosti\tools\blender_path.txt' -Raw).Trim()
